CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),created_property_id uuid NOT NULL,name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 160),phone text NOT NULL CHECK(length(trim(phone)) BETWEEN 5 AND 40),email text,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id),FOREIGN KEY(organization_id,created_property_id) REFERENCES properties(organization_id,id));
CREATE TABLE customer_locations(organization_id uuid NOT NULL,property_id uuid NOT NULL,customer_id uuid NOT NULL,PRIMARY KEY(organization_id,property_id,customer_id),FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id));
ALTER TABLE customers ENABLE ROW LEVEL SECURITY;ALTER TABLE customers FORCE ROW LEVEL SECURITY;ALTER TABLE customer_locations ENABLE ROW LEVEL SECURITY;ALTER TABLE customer_locations FORCE ROW LEVEL SECURITY;
CREATE POLICY customer_read ON customers FOR SELECT TO kost_app USING(organization_id=current_org() AND EXISTS(SELECT FROM customer_locations c WHERE c.organization_id=customers.organization_id AND c.customer_id=customers.id AND can_read_pricing(c.organization_id,c.property_id)));
CREATE POLICY customer_insert ON customers FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,created_property_id) AND created_by=current_actor());
CREATE POLICY customer_location_read ON customer_locations FOR SELECT TO kost_app USING(organization_id=current_org() AND can_read_pricing(organization_id,property_id));CREATE POLICY customer_location_insert ON customer_locations FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id));GRANT SELECT,INSERT ON customers,customer_locations TO kost_app;
ALTER TABLE bookings ADD COLUMN origin text CHECK(origin='staff'),ADD COLUMN customer_id uuid,ADD COLUMN quote_id uuid REFERENCES pricing_quotes(id),ADD COLUMN quote_expires_at timestamptz,ADD COLUMN planned_months integer CHECK(planned_months BETWEEN 1 AND 60),ADD COLUMN occupant_count integer CHECK(occupant_count>0),ADD COLUMN created_by uuid REFERENCES users(id),ADD COLUMN hold_deadline timestamptz,ADD COLUMN accepted_at timestamptz,ADD COLUMN decision_reason text,ADD CONSTRAINT booking_customer FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id),ADD CONSTRAINT booking_staff_shape CHECK(origin IS NULL OR(customer_id IS NOT NULL AND quote_id IS NOT NULL AND quote_expires_at IS NOT NULL AND planned_months IS NOT NULL AND occupant_count IS NOT NULL AND created_by IS NOT NULL AND pricing_snapshot IS NOT NULL));
ALTER TABLE bookings ADD CONSTRAINT booking_org_id UNIQUE(organization_id,id);
CREATE TABLE booking_consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,booking_id uuid NOT NULL,quote_id uuid NOT NULL REFERENCES pricing_quotes(id),booking_version integer NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL DEFAULT 'staff_recorded' CHECK(kind='staff_recorded'),note text NOT NULL CHECK(length(trim(note)) BETWEEN 3 AND 1000),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,booking_id) REFERENCES bookings(organization_id,id),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id),UNIQUE(booking_id,booking_version));
CREATE TABLE invoice_counters(organization_id uuid PRIMARY KEY REFERENCES organizations(id),last_value bigint NOT NULL CHECK(last_value>0));
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,customer_id uuid NOT NULL,booking_id uuid NOT NULL UNIQUE,number text NOT NULL,state text NOT NULL DEFAULT 'issued' CHECK(state IN ('issued','void')),total bigint NOT NULL CHECK(total>=0),due_at timestamptz NOT NULL,pricing_snapshot jsonb NOT NULL,issued_at timestamptz NOT NULL DEFAULT now(),voided_at timestamptz,void_reason text,created_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),UNIQUE(organization_id,id),UNIQUE(organization_id,number),FOREIGN KEY(organization_id,booking_id) REFERENCES bookings(organization_id,id),FOREIGN KEY(organization_id,property_id,customer_id) REFERENCES customer_locations(organization_id,property_id,customer_id),CHECK((state='issued' AND voided_at IS NULL AND void_reason IS NULL)OR(state='void' AND voided_at IS NOT NULL AND void_reason IS NOT NULL)));
CREATE TABLE invoice_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,invoice_id uuid NOT NULL,position integer NOT NULL CHECK(position>0),kind text NOT NULL CHECK(kind IN('rent','fee','deposit')),code text NOT NULL,label text NOT NULL,amount bigint NOT NULL CHECK(amount>=0),starts_on date NOT NULL,ends_on date NOT NULL CHECK(ends_on>starts_on),refundable boolean NOT NULL,FOREIGN KEY(organization_id,invoice_id) REFERENCES invoices(organization_id,id),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id),UNIQUE(invoice_id,position));
CREATE TABLE invoice_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,invoice_id uuid NOT NULL,amount bigint NOT NULL CHECK(amount<>0),reason text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,invoice_id) REFERENCES invoices(organization_id,id),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id));
CREATE TABLE booking_events_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,booking_id uuid NOT NULL,event text NOT NULL CHECK(event IN('accepted','expired')),created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,FOREIGN KEY(organization_id,booking_id) REFERENCES bookings(organization_id,id),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id),UNIQUE(booking_id,event));
CREATE TABLE in_app_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,property_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES users(id),event_id uuid NOT NULL REFERENCES booking_events_outbox(id),booking_id uuid NOT NULL,title text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),read_at timestamptz,UNIQUE(event_id,user_id),FOREIGN KEY(organization_id,booking_id) REFERENCES bookings(organization_id,id),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['booking_consents','invoices','invoice_lines','invoice_adjustments','booking_events_outbox','in_app_notifications'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY finance_scope_read ON %I FOR SELECT TO kost_app USING(can_read_pricing(organization_id,property_id))',t);END LOOP;END $$;
DROP POLICY scoped_read ON bookings;CREATE POLICY booking_read ON bookings FOR SELECT TO kost_app USING(origin='staff' AND can_read_pricing(organization_id,property_id));CREATE POLICY booking_insert ON bookings FOR INSERT TO kost_app WITH CHECK(origin='staff' AND state='pending' AND created_by=current_actor() AND can_manage_inventory(organization_id,property_id));CREATE POLICY booking_update ON bookings FOR UPDATE TO kost_app USING(origin='staff' AND can_manage_inventory(organization_id,property_id)) WITH CHECK(origin='staff' AND can_manage_inventory(organization_id,property_id));GRANT SELECT,INSERT ON bookings TO kost_app;GRANT UPDATE(state,version,pricing_snapshot,quote_id,quote_expires_at,hold_deadline,accepted_at,decision_reason) ON bookings TO kost_app;
CREATE POLICY consent_insert ON booking_consents FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id) AND actor_id=current_actor());CREATE POLICY invoice_insert ON invoices FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id));CREATE POLICY lines_insert ON invoice_lines FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id));CREATE POLICY outbox_insert ON booking_events_outbox FOR INSERT TO kost_app WITH CHECK(can_manage_inventory(organization_id,property_id));
CREATE POLICY notification_actor_read ON in_app_notifications AS RESTRICTIVE FOR SELECT TO kost_app USING(user_id=current_actor());CREATE POLICY notification_read_mark ON in_app_notifications FOR UPDATE TO kost_app USING(user_id=current_actor() AND can_read_pricing(organization_id,property_id)) WITH CHECK(user_id=current_actor() AND can_read_pricing(organization_id,property_id));
GRANT SELECT ON booking_consents,invoices,invoice_lines,invoice_adjustments,booking_events_outbox,in_app_notifications TO kost_app;GRANT INSERT ON booking_consents,invoices,invoice_lines,booking_events_outbox TO kost_app;GRANT UPDATE(read_at) ON in_app_notifications TO kost_app;
CREATE FUNCTION next_invoice_number(org uuid,location uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE n bigint;BEGIN IF NOT public.can_manage_inventory(org,location) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0404';END IF;INSERT INTO public.invoice_counters(organization_id,last_value)VALUES(org,1)ON CONFLICT(organization_id)DO UPDATE SET last_value=public.invoice_counters.last_value+1 RETURNING last_value INTO n;RETURN 'INV-'||lpad(n::text,greatest(8,length(n::text)),'0');END $$;REVOKE ALL ON FUNCTION next_invoice_number(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION next_invoice_number(uuid,uuid) TO kost_app;
CREATE FUNCTION guard_invoice_lines() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NOT EXISTS(SELECT FROM invoices i WHERE i.id=NEW.invoice_id AND i.organization_id=NEW.organization_id AND i.property_id=NEW.property_id AND i.created_xid=pg_current_xact_id()) THEN RAISE EXCEPTION 'INVALID_STATE' USING ERRCODE='P0409';END IF;RETURN NEW;END $$;CREATE TRIGGER invoice_line_tx_guard BEFORE INSERT ON invoice_lines FOR EACH ROW EXECUTE FUNCTION guard_invoice_lines();
CREATE FUNCTION validate_invoice_total() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE target uuid;BEGIN IF TG_TABLE_NAME='invoices' THEN target=NEW.id;ELSE target=NEW.invoice_id;END IF;IF EXISTS(SELECT FROM public.invoices i WHERE i.id=target AND i.total<>(SELECT coalesce(sum(l.amount),0) FROM public.invoice_lines l WHERE l.invoice_id=i.id)) THEN RAISE EXCEPTION 'BALANCE_CONFLICT' USING ERRCODE='P0409';END IF;RETURN NULL;END $$;REVOKE ALL ON FUNCTION validate_invoice_total() FROM PUBLIC;CREATE CONSTRAINT TRIGGER invoice_total_consistent AFTER INSERT ON invoices DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_invoice_total();CREATE CONSTRAINT TRIGGER line_total_consistent AFTER INSERT ON invoice_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_invoice_total();
CREATE FUNCTION guard_booking_change() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF current_user<>'kost_app' OR OLD.origin IS NULL THEN RETURN NEW;END IF;IF NEW.version<>OLD.version+1 OR OLD.state<>'pending' OR NEW.state NOT IN('pending','held','confirmed','rejected','cancelled') THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='P0409';END IF;IF NEW.state='confirmed' AND(NEW.pricing_snapshot#>>'{pricing,bookingMinimum}')::bigint<>0 THEN RAISE EXCEPTION 'INVALID_STATE' USING ERRCODE='P0409';END IF;IF NEW.state IN('held','confirmed') AND NEW.pricing_snapshot IS DISTINCT FROM OLD.pricing_snapshot THEN RAISE EXCEPTION 'QUOTE_CHANGED' USING ERRCODE='P0409';END IF;RETURN NEW;END $$;CREATE TRIGGER booking_change_guard BEFORE UPDATE ON bookings FOR EACH ROW EXECUTE FUNCTION guard_booking_change();
CREATE FUNCTION reserve_booking_allocation(org uuid,bid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE b public.bookings%ROWTYPE;r public.rooms%ROWTYPE;aid uuid;BEGIN SELECT * INTO b FROM public.bookings WHERE organization_id=org AND id=bid AND origin='staff';IF NOT FOUND OR NOT public.can_manage_inventory(org,b.property_id) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0404';END IF;PERFORM public.assert_entitlement_quota(org,0,0,0);PERFORM pg_advisory_xact_lock(hashtextextended('inventory-location:'||org::text||':'||b.property_id::text,0));SELECT * INTO r FROM public.rooms WHERE id=b.room_id AND organization_id=org FOR UPDATE;SELECT * INTO b FROM public.bookings WHERE id=bid AND organization_id=org FOR UPDATE;IF b.state NOT IN('held','confirmed') OR r.condition<>'ready' OR r.archived_at IS NOT NULL OR b.occupant_count>r.capacity OR EXISTS(SELECT FROM public.room_presence WHERE room_id=r.id AND exited_at IS NULL) THEN RAISE EXCEPTION 'INVALID_STATE' USING ERRCODE='P0409';END IF;INSERT INTO public.room_allocations(organization_id,property_id,room_id,kind,starts_on,ends_on,booking_id)VALUES(org,b.property_id,b.room_id,CASE WHEN b.state='held' THEN 'hold' ELSE 'stay' END,b.starts_on,b.ends_on,b.id) RETURNING id INTO aid;RETURN aid;END $$;REVOKE ALL ON FUNCTION reserve_booking_allocation(uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION reserve_booking_allocation(uuid,uuid) TO kost_app;
CREATE FUNCTION validate_accepted_booking() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE b public.bookings%ROWTYPE;BEGIN SELECT * INTO b FROM public.bookings WHERE id=NEW.id;IF b.origin='staff' AND b.state IN('held','confirmed') AND(NOT EXISTS(SELECT FROM public.invoices i WHERE i.booking_id=b.id AND i.organization_id=b.organization_id AND i.property_id=b.property_id AND i.customer_id=b.customer_id AND i.state='issued' AND i.pricing_snapshot=b.pricing_snapshot) OR NOT EXISTS(SELECT FROM public.room_allocations a WHERE a.booking_id=b.id AND a.state='active' AND a.starts_on=b.starts_on AND a.ends_on IS NOT DISTINCT FROM b.ends_on)) THEN RAISE EXCEPTION 'INVALID_STATE' USING ERRCODE='P0409';END IF;RETURN NULL;END $$;REVOKE ALL ON FUNCTION validate_accepted_booking() FROM PUBLIC;CREATE CONSTRAINT TRIGGER accepted_booking_consistent AFTER INSERT OR UPDATE ON bookings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_accepted_booking();
